 const add=async(e:React.FormEvent)=>{e.preventDefault();try{await onCreate({name,nif,email});setName('');setNif('');setEmail('');setShow(false);notify('Cliente criado com sucesso')}catch(e){notify(e instanceof Error?e.message:'Não foi possível guardar o cliente')}}
