 {show&&<Modal title="Criar centro de custo" onClose={()=>setShow(false)}><form onSubmit={add}><label className="field"><span>Cliente</span><select value={clientId} onChange={e=>setClientId(e.target.value)} required>{clients.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><Field label="Designação do centro" value={name} set={setName} required/><FormActions onCancel={()=>setShow(false)}/></form></Modal>}</>
