function People({employees,centers,clients,notify,onCreate,onUpdate,onOpen,onDelete}:{employees:Employee[],centers:Center[],clients:Client[],notify:(s:string)=>void,onCreate:(d:{name:string;role:string;centerIds:string[]})=>Promise<void>,onUpdate:(id:string,d:{name:string;role:string;employeeNumber:string;email:string;phone:string;weeklyHours:number;centerIds:string[];active:boolean})=>Promise<void>,onOpen:(id:string)=>void,onDelete:(id:string)=>Promise<void>}){
 const [show,setShow]=useState(false),[name,setName]=useState(''),[role,setRole]=useState(''),[centerIds,setCenterIds]=useState<string[]>([]),[editing,setEditing]=useState<Employee|null>(null),[filter,setFilter]=useState<'active'|'inactive'|'all'>('active'),[savingEdit,setSavingEdit]=useState(false),[deleting,setDeleting]=useState<Employee|null>(null),[deleteBusy,setDeleteBusy]=useState(false)
 const add=async(e:React.FormEvent)=>{e.preventDefault();try{await onCreate({name,role,centerIds});setName('');setRole('');setCenterIds([]);setShow(false);notify('Colaborador criado com sucesso')}catch(e){notify(e instanceof Error?e.message:'Não foi possível guardar o colaborador')}}
 const saveEdit=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();if(!editing)return;const f=new FormData(e.currentTarget);setSavingEdit(true);try{await onUpdate(editing.id,{name:String(f.get('name')),role:String(f.get('role')),employeeNumber:String(f.get('employeeNumber')),email:String(f.get('email')),phone:String(f.get('phone')),weeklyHours:Number(f.get('weeklyHours')||40),centerIds:f.getAll('centerIds').map(String),active:f.get('active')==='true'});notify('Ficha do colaborador atualizada');setEditing(null)}catch{notify('Não foi possível atualizar. Execute primeiro o SQL da versão 0.21.')}finally{setSavingEdit(false)}}
 const remove=async()=>{if(!deleting)return;setDeleteBusy(true);try{await onDelete(deleting.id);notify('Colaborador eliminado com sucesso');setDeleting(null)}catch(e){notify(e instanceof Error?e.message:'Não foi possível eliminar o colaborador')}finally{setDeleteBusy(false)}}
 const visible=employees.filter(e=>filter==='all'||(filter==='active'?e.active:!e.active))
 const centerLabel=(ids:string[])=>ids.map(id=>centers.find(c=>c.id===id)?.code).filter(Boolean).join(', ')||'Sem atribuição'
 return <><div className="people-filters"><button className={filter==='active'?'active':''} onClick={()=>setFilter('active')}>Ativos ({employees.filter(e=>e.active).length})</button><button className={filter==='inactive'?'active':''} onClick={()=>setFilter('inactive')}>Inativos ({employees.filter(e=>!e.active).length})</button><button className={filter==='all'?'active':''} onClick={()=>setFilter('all')}>Todos</button></div><div className="card table-card"><div className="card-head"><div><small>GESTÃO DE EQUIPA</small><h3>Colaboradores e alocação</h3></div><button className="primary" onClick={()=>setShow(true)}><Plus size={16}/>Adicionar colaborador</button></div>
 <div className="table people-table"><div className="tr th"><span>Colaborador</span><span>Função</span><span>Cliente</span><span>Centro de custo</span><span>Ações</span></div>{visible.map(p=>{const cs=p.centerIds.map(id=>centers.find(c=>c.id===id)).filter(Boolean) as Center[],clientNames=[...new Set(cs.map(c=>clients.find(x=>x.id===c.clientId)?.name).filter(Boolean))];return <div className={`tr ${!p.active?'inactive-row':''}`} key={p.id}><span><div className="mini-avatar">{initials(p.name)}</div><strong>{p.name}</strong>{!p.active&&<em className="inactive-badge">Inativo</em>}</span><span>{p.role}</span><span>{clientNames.length?clientNames.join(', '):'—'}</span><span>{centerLabel(p.centerIds)}</span><span className="people-actions"><button className="edit-employee" title={`Editar ${p.name}`} onClick={()=>setEditing(p)}><Pencil size={15}/></button><button className="open-portal" disabled={!p.active} onClick={()=>onOpen(p.id)}>Abrir portal</button>{p.active&&<button className="delete-employee" title={`Eliminar ${p.name}`} onClick={()=>setDeleting(p)}><Trash2 size={15}/></button>}</span></div>})}{!visible.length&&<p className="people-empty">Não existem colaboradores neste estado.</p>}</div></div>
 {show&&<Modal title="Adicionar colaborador" onClose={()=>setShow(false)}><form onSubmit={add}><Field label="Nome completo" value={name} set={setName} required/><Field label="Função" value={role} set={setRole} required/><label className="field"><span>Centros de custo (opcional)</span><select multiple className="inline-select" value={centerIds} onChange={e=>setCenterIds(Array.from(e.target.selectedOptions).map((o:HTMLOptionElement)=>o.value))}>{clients.map(client=><optgroup key={client.id} label={client.name}>{centers.filter(c=>c.clientId===client.id).map(c=><option key={c.id} value={c.id}>{c.code} · {c.name}</option>)}</optgroup>)}</select><small className="muted">Pode deixar sem seleção. Use Ctrl/Cmd+clique para selecionar vários.</small></label><FormActions onCancel={()=>setShow(false)}/></form></Modal>}
 {editing&&<Modal title="Editar colaborador" onClose={()=>!savingEdit&&setEditing(null)}><form onSubmit={saveEdit} className="employee-edit-form"><div className="form-grid"><label className="field"><span>Nome completo</span><input name="name" defaultValue={editing.name} required/></label><label className="field"><span>N.º de colaborador</span><input name="employeeNumber" defaultValue={editing.employeeNumber}/></label><label className="field"><span>Função</span><input name="role" defaultValue={editing.role} required/></label><label className="field"><span>Horas semanais</span><input name="weeklyHours" type="number" min="1" max="60" step="0.5" defaultValue={editing.weeklyHours} required/></label><label className="field"><span>Email</span><input name="email" type="email" defaultValue={editing.email}/></label><label className="field"><span>Telefone</span><input name="phone" type="tel" defaultValue={editing.phone}/></label></div><label className="field"><span>Centros de custo (opcional)</span><select multiple name="centerIds" defaultValue={editing.centerIds}>{clients.map(client=><optgroup key={client.id} label={client.name}>{centers.filter(c=>c.clientId===client.id).map(c=><option key={c.id} value={c.id}>{c.code} · {c.name}</option>)}</optgroup>)}</select><small className="muted">Pode deixar sem seleção. Use Ctrl/Cmd+clique para selecionar vários.</small></label><label className="field"><span>Estado</span><select name="active" defaultValue={String(editing.active)}><option value="true">Ativo</option><option value="false">Inativo</option></select></label><div className="form-actions"><button type="button" className="secondary" onClick={()=>setEditing(null)}>Cancelar</button><button type="submit" className="primary" disabled={savingEdit}>{savingEdit?'A guardar…':'Guardar alterações'}</button></div></form></Modal>}
 {deleting&&<Modal title="Eliminar colaborador" onClose={()=>!deleteBusy&&setDeleting(null)}><div className="delete-dialog"><div className="delete-warning"><AlertTriangle/></div><p>Tem a certeza de que pretende eliminar <strong>{deleting.name}</strong>?</p><small>O colaborador deixará de aparecer e perderá o acesso ao portal. Os registos históricos serão preservados.</small><div className="form-actions"><button className="secondary" disabled={deleteBusy} onClick={()=>setDeleting(null)}>Cancelar</button><button className="delete-confirm" disabled={deleteBusy} onClick={remove}><Trash2 size={15}/>{deleteBusy?'A eliminar…':'Eliminar colaborador'}</button></div></div></Modal>}</>
}
function Modal({title,onClose,children}:{title:string,onClose:()=>void,children:React.ReactNode}){return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><div className="modal"><div className="modal-head"><div><h3>{title}</h3></div><button onClick={onClose}><X/></button></div>{children}</div></div>}
function Field({label,value,set,type='text',required=false}:{label:string,value:string,set:(v:string)=>void,type?:string,required?:boolean}){return <label className="field"><span>{label}</span><input type={type} value={value} onChange={e=>set(e.target.value)} required={required}/></label>}
function FormActions({onCancel}:{onCancel:()=>void}){return <div className="form-actions"><button type="button" className="secondary" onClick={onCancel}>Cancelar</button><button type="submit" className="primary">Guardar</button></div>}
type EmployeeInvite={id:string;employee_id:string;code:string;expires_at:string;used_at:string|null}
function BrandingCard({companyId,logoUrl,primaryColor,slug,notify,onSaved}:{companyId:string;logoUrl:string;primaryColor:string;slug:string;notify:(s:string)=>void;onSaved:(logoUrl:string,primaryColor:string)=>void}){
 const [url,setUrl]=useState(logoUrl),[color,setColor]=useState(primaryColor||'#a67a35'),[saving,setSaving]=useState(false)
 const loginLink=slug?`${window.location.origin}/?empresa=${slug}`:''
 const save=async()=>{if(!companyId)return;setSaving(true);try{await updateCompanyBranding(companyId,{logoUrl:url.trim(),primaryColor:color});onSaved(url.trim(),color);notify('Identidade visual atualizada')}catch(e){notify(e instanceof Error?e.message:'Não foi possível guardar a identidade visual')}finally{setSaving(false)}}
 return <div className="card branding-card"><div className="card-head"><div><small>IDENTIDADE VISUAL</small><h3>Logótipo e cor da empresa</h3><p className="muted">Mostra o logótipo da sua empresa no ecrã de entrada e nos destaques da aplicação, em vez da marca NLGest Ponto por omissão.</p></div></div>
  <div className="branding-row">
   <div className="branding-preview">{url?<img src={url} alt="Pré-visualização do logótipo"/>:<span className="muted">Sem logótipo definido</span>}</div>
   <div className="branding-fields">
    <label className="field"><span>URL do logótipo (imagem alojada online)</span><input type="url" value={url} onChange={e=>setUrl(e.target.value)} placeholder="https://..."/></label>
    <label className="field branding-color-field"><span>Cor principal</span><input type="color" value={color} onChange={e=>setColor(e.target.value)}/></label>
    <button className="primary" disabled={saving} onClick={save}>{saving?'A guardar…':'Guardar identidade visual'}</button>
   </div>
  </div>
  {loginLink&&<div className="branding-link"><small>Ligação de entrada com a sua marca (envie aos colaboradores)</small><code>{loginLink}</code><button className="secondary" onClick={()=>{navigator.clipboard.writeText(loginLink);notify('Ligação copiada')}}>Copiar</button></div>}
 </div>
}
function AccessPage({profiles,employees,companyId,currentProfileId,notify,onSave,accessRole,companyLogoUrl,companyPrimaryColor,companySlug,onBrandingSaved}:{profiles:Profile[];employees:Employee[];companyId:string;currentProfileId?:string;notify:(s:string)=>void;onSave:(profileId:string,role:string,employeeId:string)=>Promise<void>;accessRole:string;companyLogoUrl:string;companyPrimaryColor:string;companySlug:string;onBrandingSaved:(logoUrl:string,primaryColor:string)=>void}){
 const [drafts,setDrafts]=useState<Record<string,{role:string;employeeId:string}>>({}),[saving,setSaving]=useState(''),[invites,setInvites]=useState<EmployeeInvite[]>([]),[generating,setGenerating]=useState('')
 useEffect(()=>{loadEmployeeInvites().then(r=>setInvites(r as EmployeeInvite[])).catch(()=>{})},[])
 const draft=(p:Profile)=>drafts[p.id]||{role:p.role,employeeId:employees.find(e=>e.profileId===p.id)?.id||''}
 const change=(p:Profile,field:'role'|'employeeId',value:string)=>setDrafts(v=>({...v,[p.id]:{...draft(p),[field]:value}}))
 const save=async(p:Profile)=>{if(p.id===currentProfileId)return;const d=draft(p);setSaving(p.id);try{await onSave(p.id,d.role,d.role==='employee'?d.employeeId:'');notify('Perfil e permissões atualizados')}catch(e){notify(e instanceof Error?e.message:'Não foi possível atualizar o perfil')}finally{setSaving('')}}
 const generate=async(employeeId:string)=>{setGenerating(employeeId);try{const created=await createEmployeeInvite(companyId,employeeId) as EmployeeInvite;setInvites(v=>[created,...v]);notify('Convite criado com sucesso')}catch{notify('Não foi possível criar o convite. Execute primeiro o SQL da versão 0.17.')}finally{setGenerating('')}}
 const copy=async(code:string)=>{await navigator.clipboard.writeText(code);notify('Código copiado')}
 const available=employees.filter(e=>!e.profileId)
 return <div className="access-page">{accessRole==='company_admin'&&<BrandingCard companyId={companyId} logoUrl={companyLogoUrl} primaryColor={companyPrimaryColor} slug={companySlug} notify={notify} onSaved={onBrandingSaved}/>}<div className="card-head"><div><small>SEGURANÇA E ACESSOS</small><h3>Perfis e permissões</h3><p className="muted">Associe cada conta ao nível de acesso e, no caso de colaborador, à respetiva ficha.</p></div></div><div className="card access-list"><div className="access-row access-head"><span>Conta</span><span>Perfil</span><span>Colaborador associado</span><span></span></div>{profiles.map(p=>{const d=draft(p),own=p.id===currentProfileId;return <div className={`access-row ${own?'protected':''}`} key={p.id}><div className="access-account"><div className="mini-avatar">{initials(p.name||p.email)}</div><div><strong>{p.name||p.email}</strong><small>{p.email}</small>{own&&<em><ShieldCheck size={12}/> Conta atual · protegida</em>}</div></div><select value={d.role} disabled={own} onChange={e=>change(p,'role',e.target.value)}><option value="company_admin">Administrador</option><option value="management">Administração</option><option value="hr_manager">Responsável de RH</option><option value="hr_admin">Administrativa de RH</option><option value="site_manager">Responsável de Obra</option><option value="employee">Colaborador</option></select><select value={d.employeeId} disabled={own||d.role!=='employee'} onChange={e=>change(p,'employeeId',e.target.value)}><option value="">Sem associação</option>{employees.map(e=><option key={e.id} value={e.id}>{e.name}</option>)}</select><button className="primary" disabled={own||saving===p.id||d.role==='employee'&&!d.employeeId} onClick={()=>save(p)}>{own?'Protegida':saving===p.id?'A guardar…':'Guardar'}</button></div>})}</div>
 <div className="invite-heading"><div><small>CONVITES DE ACESSO</small><h3>Ligar colaboradores às respetivas contas</h3><p className="muted">Crie um código, envie-o ao colaborador e peça-lhe para o introduzir ao criar a conta. Cada código dura sete dias e só pode ser usado uma vez.</p></div><KeyRound/></div>
 <div className="card invite-list">{available.length?available.map(employee=>{const invite=invites.find(i=>i.employee_id===employee.id&&!i.used_at&&new Date(i.expires_at)>new Date());return <div className="invite-row" key={employee.id}><div className="access-account"><div className="mini-avatar">{initials(employee.name)}</div><div><strong>{employee.name}</strong><small>{employee.role||'Colaborador'}</small></div></div>{invite?<><div className="invite-code"><code>{invite.code}</code><small>Válido até {new Date(invite.expires_at).toLocaleDateString('pt-PT')}</small></div><button className="secondary" onClick={()=>copy(invite.code)}><Copy size={15}/>Copiar</button><button className="text" onClick={()=>generate(employee.id)}>Novo código</button></>:<button className="primary invite-create" disabled={generating===employee.id||!companyId} onClick={()=>generate(employee.id)}><KeyRound size={15}/>{generating===employee.id?'A criar…':'Criar convite'}</button>}</div>}):<div className="invite-empty"><CheckCircle2/>Todos os colaboradores já têm uma conta associada.</div>}</div></div>
}
function Placeholder(){return <div className="empty card"><div className="empty-icon"><Settings/></div><h2>Configuração</h2><p>Defina a identidade, regras de picagem e integração com o PHC.</p><button className="primary">Configurar módulo</button></div>}

const billingLabel=(s:string)=>({trial:'Em teste',active:'Ativa',overdue:'Em atraso',suspended:'Suspensa',cancelled:'Cancelada'}[s]||s)
function PlatformPanel({onExit,onSignOut}:{onExit:()=>void,onSignOut:()=>void}){
 const [companies,setCompanies]=useState<Company[]>([]),[loading,setLoading]=useState(true),[toast,setToast]=useState('')
 const [creating,setCreating]=useState(false),[name,setName]=useState(''),[clientAdminEmail,setClientAdminEmail]=useState(''),[monthlyFee,setMonthlyFee]=useState(''),[busy,setBusy]=useState(false)
 const [inviteResult,setInviteResult]=useState<{company:string,code:string,subscriptionUrl?:string,subscriptionError?:string}|null>(null)
 const [editing,setEditing]=useState<Company|null>(null),[savingEdit,setSavingEdit]=useState(false)
 const [deleting,setDeleting]=useState<Company|null>(null),[deleteConfirm,setDeleteConfirm]=useState(''),[deleteBusy,setDeleteBusy]=useState(false)
 const notify=(m:string)=>{setToast(m);setTimeout(()=>setToast(''),3500)}
 const load=async()=>{setLoading(true);try{setCompanies(await loadPlatformCompanies() as Company[])}catch{notify('Não foi possível carregar as empresas. Execute primeiro o SQL da versão 0.22.')}finally{setLoading(false)}}
 useEffect(()=>{load()},[])
 const create=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);try{const fee=monthlyFee?Number(monthlyFee):undefined;const id=await createPlatformCompany({name,adminEmail:clientAdminEmail,monthlyFee:fee});const invite=await createCompanyAdminInvite(id) as CompanyAdminInvite;let subscriptionUrl:string|undefined,subscriptionError:string|undefined;if(fee){try{subscriptionUrl=await createCompanySubscriptionLink({companyId:id,companyName:name,monthlyFee:fee,adminEmail:clientAdminEmail})}catch(e){subscriptionError=e instanceof Error?e.message:'Não foi possível gerar o link de pagamento.'}}setInviteResult({company:name,code:invite.code,subscriptionUrl,subscriptionError});setName('');setClientAdminEmail('');setMonthlyFee('');setCreating(false);load()}catch(e){notify(e instanceof Error?e.message:'Não foi possível criar a empresa')}finally{setBusy(false)}}
 const regenerate=async(c:Company)=>{setBusy(true);try{const invite=await createCompanyAdminInvite(c.id) as CompanyAdminInvite;setInviteResult({company:c.name,code:invite.code});notify('Novo código gerado')}catch{notify('Não foi possível gerar o convite')}finally{setBusy(false)}}
 const copy=async(code:string)=>{await navigator.clipboard.writeText(code);notify('Código copiado')}
 const saveEdit=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();if(!editing)return;const f=new FormData(e.currentTarget);setSavingEdit(true);try{await updatePlatformCompany(editing.id,{billingStatus:String(f.get('billingStatus')),monthlyFee:f.get('monthlyFee')?Number(f.get('monthlyFee')):undefined,nextDueDate:String(f.get('nextDueDate')||''),billingNotes:String(f.get('billingNotes')||''),active:f.get('active')==='true'});notify('Faturação atualizada');setEditing(null);load()}catch{notify('Não foi possível guardar')}finally{setSavingEdit(false)}}
 const removeCompany=async()=>{if(!deleting)return;setDeleteBusy(true);try{await deletePlatformCompany(deleting.id);notify('Empresa eliminada');setDeleting(null);setDeleteConfirm('');load()}catch(e){notify(e instanceof Error?e.message:'Não foi possível eliminar a empresa')}finally{setDeleteBusy(false)}}
 const toggleAccess=async(c:Company)=>{setBusy(true);try{await setCompanyActive(c.id,!c.active);notify(c.active?`Acesso de ${c.name} suspenso`:`Acesso de ${c.name} reativado`);load()}catch(e){notify(e instanceof Error?e.message:'Não foi possível atualizar o acesso')}finally{setBusy(false)}}
 return <div className="platform-page">
  <header className="platform-header"><div><small>PLATAFORMA</small><h1>Empresas clientes</h1></div><div className="platform-header-actions"><button className="secondary" onClick={onExit}>Ver a minha empresa</button><button className="edit-punch" title="Terminar sessão" onClick={onSignOut}><LogOut size={18}/></button></div></header>
  <div className="content">
   <div className="card-head"><div><small>{companies.length} EMPRESA{companies.length===1?'':'S'}</small><h3>Contas e avenças</h3></div><button className="primary" onClick={()=>setCreating(true)}><Plus size={16}/>Nova empresa</button></div>
   <div className="card table-card"><div className="table platform-table"><div className="tr th"><span>Empresa</span><span>Estado</span><span>Avença</span><span>Próx. vencimento</span><span>Ações</span></div>
    {loading?<p className="people-empty">A carregar…</p>:companies.length?companies.map(c=><div className="tr" key={c.id}><span><strong>{c.name}</strong>{c.admin_email&&<small>{c.admin_email}</small>}</span><span><em className={`billing-badge ${c.billing_status}`}>{billingLabel(c.billing_status)}</em></span><span>{c.monthly_fee!=null?`${c.monthly_fee} €/mês`:'—'}</span><span>{c.next_due_date?new Date(c.next_due_date).toLocaleDateString('pt-PT'):'—'}</span><span className="people-actions"><button className="edit-employee" title="Editar faturação" onClick={()=>setEditing(c)}><Pencil size={15}/></button><button className="text" disabled={busy} onClick={()=>regenerate(c)}>Novo código</button><button className={`suspend-access ${c.active?'':'reactivate'}`} disabled={busy} title={c.active?`Suspender acesso de ${c.name}`:`Reativar acesso de ${c.name}`} onClick={()=>toggleAccess(c)}>{c.active?<Ban size={15}/>:<Play size={15}/>}</button><button className="delete-employee" title={`Eliminar ${c.name}`} onClick={()=>setDeleting(c)}><Trash2 size={15}/></button></span></div>):<p className="people-empty">Ainda não existem empresas clientes.</p>}
   </div></div>
  </div>
  {creating&&<Modal title="Nova empresa cliente" onClose={()=>!busy&&setCreating(false)}><form onSubmit={create}><Field label="Nome da empresa" value={name} set={setName} required/><Field label="Email do administrador do cliente" value={clientAdminEmail} set={setClientAdminEmail} type="email" required/><Field label="Valor da avença (€/mês, opcional)" value={monthlyFee} set={setMonthlyFee} type="number"/><FormActions onCancel={()=>setCreating(false)}/></form></Modal>}
  {inviteResult&&<Modal title="Empresa criada" onClose={()=>setInviteResult(null)}><div className="delete-dialog"><p>Envie este código a <strong>{inviteResult.company}</strong> para criar a conta de administrador.</p><div className="invite-code"><code>{inviteResult.code}</code></div><div className="form-actions"><button className="secondary" onClick={()=>copy(inviteResult.code)}><Copy size={15}/>Copiar código</button></div>{inviteResult.subscriptionUrl&&<><p style={{marginTop:'1rem'}}>Envie também este link para o cliente ativar a avença mensal (pagamento automático):</p><div className="invite-code"><code style={{wordBreak:'break-all'}}>{inviteResult.subscriptionUrl}</code></div><div className="form-actions"><button className="secondary" onClick={()=>copy(inviteResult.subscriptionUrl as string)}><Copy size={15}/>Copiar link de pagamento</button></div></>}{inviteResult.subscriptionError&&<p className="muted" style={{marginTop:'1rem',color:'#b3452c'}}>Não foi possível gerar o link de pagamento automaticamente ({inviteResult.subscriptionError}). Pode criar a empresa na mesma e gerar o link mais tarde.</p>}<div className="form-actions"><button className="primary" onClick={()=>setInviteResult(null)}>Concluído</button></div></div></Modal>}
  {editing&&<Modal title={`Faturação — ${editing.name}`} onClose={()=>!savingEdit&&setEditing(null)}><form onSubmit={saveEdit} className="employee-edit-form"><label className="field"><span>Estado da conta</span><select name="billingStatus" defaultValue={editing.billing_status}><option value="trial">Em teste</option><option value="active">Ativa</option><option value="overdue">Em atraso</option><option value="suspended">Suspensa</option><option value="cancelled">Cancelada</option></select></label><label className="field"><span>Valor da avença (€/mês)</span><input name="monthlyFee" type="number" step="0.01" defaultValue={editing.monthly_fee??''}/></label><label className="field"><span>Próximo vencimento</span><input name="nextDueDate" type="date" defaultValue={editing.next_due_date||''}/></label><label className="field"><span>Notas</span><textarea name="billingNotes" rows={3} defaultValue={editing.billing_notes||''}/></label><label className="field"><span>Conta ativa</span><select name="active" defaultValue={String(editing.active)}><option value="true">Ativa</option><option value="false">Suspensa (bloqueia o acesso)</option></select></label><div className="form-actions"><button type="button" className="secondary" onClick={()=>setEditing(null)}>Cancelar</button><button type="submit" className="primary" disabled={savingEdit}>{savingEdit?'A guardar…':'Guardar'}</button></div></form></Modal>}
  {deleting&&<Modal title="Eliminar empresa" onClose={()=>!deleteBusy&&(setDeleting(null),setDeleteConfirm(''))}><div className="delete-dialog"><div className="delete-warning"><AlertTriangle/></div><p>Tem a certeza de que pretende eliminar <strong>{deleting.name}</strong>?</p><small>Esta ação é definitiva: elimina a empresa e todos os seus dados — colaboradores, picagens, ausências, documentos e códigos de acesso. Não pode ser revertida. As contas de acesso (login) dos utilizadores desta empresa deixam de ter empresa associada.</small><label className="field"><span>Escreva <strong>{deleting.name}</strong> para confirmar</span><input value={deleteConfirm} onChange={e=>setDeleteConfirm(e.target.value)} autoFocus/></label><div className="form-actions"><button className="secondary" disabled={deleteBusy} onClick={()=>{setDeleting(null);setDeleteConfirm('')}}>Cancelar</button><button className="delete-confirm" disabled={deleteBusy||deleteConfirm!==deleting.name} onClick={removeCompany}><Trash2 size={15}/>{deleteBusy?'A eliminar…':'Eliminar empresa'}</button></div></div></Modal>}
  {toast&&<div className="toast success">{toast}</div>}
 </div>
}

function Auth(){
 const [email,setEmail]=useState(''),[password,setPassword]=useState(''),[fullName,setFullName]=useState(''),[inviteCode,setInviteCode]=useState(''),[mode,setMode]=useState<'login'|'signup'>('login'),[message,setMessage]=useState(''),[busy,setBusy]=useState(false)
 const [brand,setBrand]=useState<{name:string;logo_url:string|null;primary_color:string|null}|null>(null)
 useEffect(()=>{const fromUrl=new URLSearchParams(window.location.search).get('empresa');const slug=fromUrl||localStorage.getItem('nlg-empresa-slug');if(!slug)return;loadCompanyBranding(slug).then(r=>{if(r){setBrand(r);localStorage.setItem('nlg-empresa-slug',slug)}else if(fromUrl){localStorage.removeItem('nlg-empresa-slug')}}).catch(()=>{})},[])
 const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setMessage('')
  const result=mode==='login'?await supabase.auth.signInWithPassword({email,password}):await supabase.auth.signUp({email,password,options:{data:{full_name:fullName,invite_code:inviteCode.trim().toUpperCase()}}})
  setBusy(false)
  if(result.error)setMessage(result.error.message)
  else if(mode==='signup'&&!result.data.session)setMessage('Conta criada. Confirme o email recebido antes de entrar.')
 }
 return <div className="auth-page"><div className="auth-panel" style={brand?.primary_color?({'--accent':brand.primary_color} as React.CSSProperties):undefined}>{brand?.logo_url?<img src={brand.logo_url} alt={brand.name} className="auth-logo"/>:<span className="eyebrow">GESTÃO DE PONTO</span>}<h1>{mode==='login'?'Bem-vindo':'Criar conta'}</h1><p>{mode==='login'?(brand?.name?`Entre para aceder à área de ${brand.name}.`:'Entre para gerir clientes, centros de custo e colaboradores.'):'Introduza o código de acesso fornecido pelo administrador da plataforma.'}</p><form onSubmit={submit}>{mode==='signup'&&<><Field label="Nome completo" value={fullName} set={setFullName} required/><Field label="Código de acesso" value={inviteCode} set={setInviteCode} required/></>}<Field label="Email" value={email} set={setEmail} type="email" required/><Field label="Palavra-passe" value={password} set={setPassword} type="password" required/><button className="primary auth-submit" disabled={busy}>{busy?'A processar…':mode==='login'?'Entrar':'Criar conta'}</button></form>{message&&<div className="auth-message">{message}</div>}<button className="auth-switch" onClick={()=>{setMode(mode==='login'?'signup':'login');setMessage('')}}>{mode==='login'?'Ainda não tem conta? Criar conta':'Já tem conta? Entrar'}</button></div></div>
}
function Root(){
 const [session,setSession]=useState<Session|null>(null),[loading,setLoading]=useState(true)
 const [platformAdmin,setPlatformAdmin]=useState<boolean|null>(null)
 const [viewMode,setViewMode]=useState<'platform'|'company'>('platform')
 useEffect(()=>{if(!supabaseConfigured){setLoading(false);return}supabase.auth.getSession().then(({data})=>{setSession(data.session);setLoading(false)});const {data}=supabase.auth.onAuthStateChange((_event,next)=>setSession(next));return()=>data.subscription.unsubscribe()},[])
 useEffect(()=>{if(!session){setPlatformAdmin(null);return}checkPlatformAdmin().then(setPlatformAdmin).catch(()=>setPlatformAdmin(false))},[session?.user?.id])
 if(loading)return <div className="app-loading">A carregar…</div>
 if(!supabaseConfigured)return <App/>
 if(!session)return <Auth/>
 if(platformAdmin===null)return <div className="app-loading">A carregar…</div>
 if(platformAdmin&&viewMode==='platform')return <PlatformPanel onExit={()=>setViewMode('company')} onSignOut={()=>supabase.auth.signOut()}/>
 return <App email={session.user.email} fullName={session.user.user_metadata?.full_name} inviteCode={session.user.user_metadata?.invite_code} onBackToPlatform={platformAdmin?()=>setViewMode('platform'):undefined}/>
}

createRoot(document.getElementById('root')!).render(<React.StrictMode><Root/></React.StrictMode>)
